      const userToken = await getNewUserToken("user_insufficient_stock@qa.com");
      const uniqueName = "Produto Estoque Insuficiente";
      const postRes = await request(app)
        .post("/produtos")
        .set("authorization", token)
        .send({
          nome: uniqueName,
          preco: 100,
